252	                    chunk.len()
253	                } else {
254	                    let mut split_ix = cmp::min(
255	                        chunk::MIN_BASE.saturating_sub(last_chunk.text.len()),
256	                        chunk.len(),
257	                    );
258	                    while !chunk.is_char_boundary(split_ix) {
