260	                    }
261	                    split_ix
262	                };
263	
264	                let (suffix, remainder) = chunk.split_at(split_ix);
265	                last_chunk.append(suffix);
266	                chunk = remainder;
267	            },
268	            (),
269	        );
270	
271	        if !chunk.is_empty() {
272	            self.chunks.push(chunk.into(), ());
273	        }
274	    }
